xinshengCustomCss:
@import url("https://fontsapi.zeoseven.com/467/main/result.css");

.xt-root {
  --xt-bg: #1a1718;
  --xt-text: #d4c9b8;
  --xt-text-sub: #9a8b7a;
  --xt-text-muted: #4d3f3a;
  --xt-accent: #c0392b;
  --xt-accent-bg: rgba(192, 57, 43, 0.1);
  --xt-border: #3d2e2a;
  --xt-radius: 8px;
  --xt-radius-sm: 4px;
  --xt-font: "NanoOldSong-A", "Special Elite", "Courier New", monospace;
  --xt-glow-color: rgba(192, 57, 43, 0.3);

  background: #1a1718;
  background-image: 
    repeating-linear-gradient(0deg, 
      rgba(60, 50, 45, 0.3) 0px,
      rgba(60, 50, 45, 0.3) 1px,
      transparent 1px,
      transparent 3px
    ),
    radial-gradient(ellipse at 20% 50%, rgba(80, 60, 50, 0.2) 0%, transparent 70%);
  border: 2px solid #3d2e2a;
  box-shadow: 
    0 0 30px rgba(0, 0, 0, 0.8),
    inset 0 0 60px rgba(30, 20, 15, 0.5);
  position: relative;
  overflow-y: auto;
  overflow-x: hidden;
  height: 700px;
  max-height: 700px;
}

.xt-root::before {
  content: "TOP SECRET";
  position: sticky;
  top: 50%;
  display: block;
  transform: translateY(-50%) rotate(-25deg);
  font-size: 48px;
  font-weight: 900;
  color: rgba(192, 57, 43, 0.10);
  letter-spacing: 16px;
  white-space: nowrap;
  pointer-events: none;
  z-index: 0;
  font-family: "NanoOldSong-A", "Arial Black", sans-serif;
  text-shadow: 0 0 30px rgba(192, 57, 43, 0.06);
  text-align: center;
  width: 100%;
  height: 0;
  overflow: visible;
}

.xt-root::after {
  content: none;
}

.xt-content,
.xt-row,
.xt-card,
.xt-section,
.xt-collapse,
.xt-footer,
.xt-divider,
.xt-text {
  position: relative;
  z-index: 1;
}

.xt-content {
  overflow: visible !important;
  height: auto !important;
}

/* ── 头像 + 信息行 ── */
.xt-row:first-of-type {
  display: flex;
  gap: 16px;
  align-items: stretch;
  flex-wrap: nowrap;
}

/* 左侧：头像卡片 */
.xt-row:first-of-type > .xt-card:first-child {
  flex: 0 0 100px;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  box-shadow: none !important;
}
.xt-row:first-of-type > .xt-card:first-child .xt-image {
  width: 100%;
  aspect-ratio: 3/4;
  border-radius: 2px;
  overflow: hidden;
  background: #2a1f1a;
  border: none;
}
.xt-row:first-of-type > .xt-card:first-child .xt-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  filter: grayscale(0.5) contrast(1.1);
}

/* 右侧：信息卡片 */
.xt-row:first-of-type > .xt-card:last-child {
  flex: 1;
  background: transparent !important;
  border: none !important;
  padding: 0 !important;
  box-shadow: none !important;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 2px;
}

/* 四个信息字段 */
.xt-row:first-of-type .xt-text-fullName,
.xt-row:first-of-type .xt-text-alias,
.xt-row:first-of-type .xt-text-caseNumber,
.xt-row:first-of-type .xt-text-idNumber {
  display: block !important;
  width: 100% !important;
  color: #d4c9b8 !important;
  font-size: 13px !important;
  padding: 2px 0 !important;
  font-family: "NanoOldSong-A", "Courier New", monospace !important;
  background: transparent !important;
  border: none !important;
  border-bottom: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  margin: 0 !important;
  line-height: 1.6 !important;
}

.xt-row:first-of-type .xt-text-fullName::before {
  content: "姓名：";
  color: #6a5a4a;
}
.xt-row:first-of-type .xt-text-alias::before {
  content: "代号：";
  color: #6a5a4a;
}
.xt-row:first-of-type .xt-text-caseNumber::before {
  content: "档案号：";
  color: #6a5a4a;
}
.xt-row:first-of-type .xt-text-idNumber::before {
  content: "身份证号：";
  color: #6a5a4a;
}

/* ── 以下全部保留你的原有样式 ── */

.xt-text {
  color: #d4c9b8;
  font-size: 12px;
  padding: 3px 6px;
  font-family: "NanoOldSong-A", "Courier New", monospace;
  display: block !important;
  background: transparent !important;
  border: none !important;
  border-bottom: none !important;
  border-radius: 0 !important;
  margin-bottom: 1px;
}

.xt-content .xt-divider + .xt-text,
.xt-content .xt-divider + .xt-text + .xt-text,
.xt-content .xt-divider + .xt-text + .xt-text + .xt-text,
.xt-content .xt-divider + .xt-text + .xt-text + .xt-text + .xt-text,
.xt-content .xt-divider + .xt-text + .xt-text + .xt-text + .xt-text + .xt-text,
