  --xt-accent-bg: rgba(217, 74, 58, 0.08);
  --xt-border: #e8c8a8;
  --xt-radius: 20px;
  --xt-font: 'ZCOOL KuaiLe', cursive;

  background: var(--xt-bg);
  border: 5px solid #b84a3a;
  border-radius: 28px;
  box-shadow: 
    inset 0 4px 0 #8a3528,
    inset 0 6px 0 #6f2a1f,
    inset 0 -4px 0 #8a3528,
    inset 0 -6px 0 #6f2a1f,
    inset 0 0 30px rgba(120, 40, 20, 0.06),
    0 4px 12px rgba(120, 40, 20, 0.15);
  padding: 14px 14px 12px 14px;
  max-width: 420px;
  margin: 0 auto;
  overflow: visible;
  position: relative;
}

/* ===== 整体内容容器 ===== */
.xt-content {
  max-height: 520px !important;
  overflow-y: auto !important;
  padding-right: 4px;
  display: block !important;
}

/* ===== 顶部标题 ===== */
.xt-section:first-of-type .xt-section-title {
  font-size: 32px;
  font-weight: 900;
  color: #d94a3a;
  text-align: center;
  letter-spacing: 12px;
  text-shadow: 3px 3px 0 #f5d6b8, 6px 6px 0 rgba(180, 60, 30, 0.15);
  padding: 0 0 4px 0;
  display: block;
  border-bottom: none;
}
.xt-section:first-of-type .xt-section-body {
  display: none;
}

/* ===== 折叠信封 ===== */
.xt-collapse {
  background: transparent;
  border: none;
  box-shadow: none;
  margin-bottom: 6px;
  overflow: visible;
}

.xt-collapse-header {
  background: #d94a3a;
  padding: 10px 14px;
  border-radius: 16px 16px 0 0;
  font-size: 17px;
  font-weight: bold;
  text-align: center;
  cursor: pointer;
  box-shadow: 
    inset 0 -3px 0 #b84a3a,
    0 2px 0 #b84a3a,
    0 4px 0 #8a3528;
  line-height: 1.3;
  color: #fff;
  border-bottom: 3px solid #b84a3a;
  letter-spacing: 1px;
}

.xt-collapse-header::after {
  content: "" !important;
  display: none !important;
}

.xt-collapse-body {
  padding: 0 12px;
  background: #fdf3e0;
  max-height: 48px;
  overflow: hidden;
  transition: max-height 0.5s ease, padding 0.4s ease;
  border-radius: 0 0 16px 16px;
  border-left: 2.5px solid #d94a3a;
  border-right: 2.5px solid #d94a3a;
  border-bottom: 2.5px solid #d94a3a;
  box-shadow: 0 4px 0 #b84a3a, 0 6px 12px rgba(180, 60, 30, 0.12);
}

#xt-t1:checked ~ .xt-content .xt-collapse-body {
  max-height: 600px !important;
  padding: 10px 12px 14px 12px !important;
  overflow-y: auto !important;
}

/* ===== 信封内部字段 ===== */
.xt-text-novelTitle {
  font-size: 20px;
  font-weight: 700;
  color: #b84a3a;
  background: #f9f6f0;
  text-align: center;
  display: block !important;
  padding: 2px 0 6px 0;
  border-bottom: 2px solid #f5d6b8;
  margin-bottom: 4px;
  line-height: 1.4;
  word-break: break-word;
}

.xt-text-noticeText {
  font-size: 12px;
  color: #b84a3a;
  text-align: center;
  padding: 4px 10px;
  background: rgba(217, 74, 58, 0.06);
  border-radius: 6px;
  display: block !important;
  margin: 0 0 4px 0;
  border: none;
  word-break: break-word;
}

.xt-section-title {
  display: none;
}

.xt-section-body {
  background: rgba(255, 240, 225, 0.4);
  border-left: 4px solid #d94a3a;
  padding: 8px 12px;
  border-radius: 8px;
  font-size: 14px;
  line-height: 1.8;
  color: #b84a3a;
  background: #f9f6f0; 
  margin: 4px 0 6px 0;
  word-break: break-word;
}

.xt-text-punishText {
  font-size: 12px;
  color: #b84a3a;
  text-align: center;
  padding: 4px 10px;
  background: rgba(217, 74, 58, 0.06);
  border-radius: 6px;
  display: block !important;
  margin: 0 0 4px 0;
  border: none;
  word-break: break-word;
}

.xt-divider {
  border-top: 2px dashed #e8c8a8;
  margin: 4px 0;
  background: none;
  height: auto;
}
/* ============================================================
   左右互搏区
   ============================================================ */
.xt-card:first-of-type {
  background: rgba(255, 248, 240, 0.7);
  border-radius: 16px;
  border: 2.5px solid #e8c8a8;
  padding: 6px 10px 4px 10px;
  box-shadow: 
    inset 0 1px 0 rgba(255, 255, 255, 0.6),
