    0 1px 0 #d4b89a,
    0 3px 0 #c4a082,
    0 6px 16px rgba(180, 60, 30, 0.12);
}
.xt-card:first-of-type * {
  word-break: break-word;
  overflow-wrap: break-word;
  max-width: 100%;
}

.xt-card-title {
  font-size: 16px;
  font-weight: 700;
  color: #d94a3a;
  text-align: center;
  letter-spacing: 4px;
  padding: 0 0 4px 0;
  border-bottom: 2px solid #f5d6b8;
  display: block !important;
  margin-bottom: 4px;
  flex-shrink: 0;
}

/* ---- 七个气泡 ---- */
.xt-card:first-of-type .xt-text-bubble1,
.xt-card:first-of-type .xt-text-bubble2,
.xt-card:first-of-type .xt-text-bubble3,
.xt-card:first-of-type .xt-text-bubble4,
.xt-card:first-of-type .xt-text-bubble5,
.xt-card:first-of-type .xt-text-bubble6,
.xt-card:first-of-type .xt-text-bubbleFinal {
